    dcs = [
        r
        for r in _csv_rows(root, "soony/master", "sites*.csv", ("site_id", "type"))
        if (r.get("type") or "").lower() == "dc"
    ]
    if dcs:
        city = (dcs[0].get("city") or "").strip()
