                table = find_xlsx_table(path, required)
                if table:
                    return kind, {"sheet": table[0], "header_row": table[1]}
            tables = find_workbook_tables(path)
            if tables:
                return "workbook", {"tables": tables}
        elif suffix == ".json":
            kind = _best_layout(set(flatten(load_json(path))), JSON_LAYOUTS)
            if kind:
